/*
  JKTurnos - Esquema completo para hosting (migracion unica Inicial).
  Base: w370423_jkturnos (servidor sql2016).
  OPCIONAL: la app ya crea la BD sola con MigrateDatabaseToLatestVersion.
  Este script es solo para pre-crear el esquema manualmente en el panel.
*/
USE [w370423_jkturnos];
GO

DECLARE @CurrentMigration [nvarchar](max)

IF object_id('[dbo].[__MigrationHistory]') IS NOT NULL
    SELECT @CurrentMigration =
        (SELECT TOP (1) 
        [Project1].[MigrationId] AS [MigrationId]
        FROM ( SELECT 
        [Extent1].[MigrationId] AS [MigrationId]
        FROM [dbo].[__MigrationHistory] AS [Extent1]
        WHERE [Extent1].[ContextKey] = N'JKTurnos.Migrations.Configuration'
        )  AS [Project1]
        ORDER BY [Project1].[MigrationId] DESC)

IF @CurrentMigration IS NULL
    SET @CurrentMigration = '0'

IF @CurrentMigration < '202608182313336_Inicial'
BEGIN
    CREATE TABLE [dbo].[Clientes] (
        [Id] [int] NOT NULL IDENTITY,
        [TenantId] [int] NOT NULL,
        [Nombre] [nvarchar](120) NOT NULL,
        [Telefono] [nvarchar](50),
        [Email] [nvarchar](120),
        [Direccion] [nvarchar](250),
        [Notas] [nvarchar](max),
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.Clientes] PRIMARY KEY ([Id])
    )
    CREATE TABLE [dbo].[ConfiguracionTenants] (
        [Id] [int] NOT NULL IDENTITY,
        [TenantId] [int] NOT NULL,
        [NombreComercial] [nvarchar](150) NOT NULL,
        [Telefono] [nvarchar](50),
        [Email] [nvarchar](150),
        [Direccion] [nvarchar](250),
        [LogoUrl] [nvarchar](500),
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.ConfiguracionTenants] PRIMARY KEY ([Id])
    )
    CREATE INDEX [IX_TenantId] ON [dbo].[ConfiguracionTenants]([TenantId])
    CREATE TABLE [dbo].[Tenants] (
        [Id] [int] NOT NULL IDENTITY,
        [Nombre] [nvarchar](max),
        [Subdominio] [nvarchar](max),
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.Tenants] PRIMARY KEY ([Id])
    )
    CREATE TABLE [dbo].[EstadoTurnoes] (
        [Id] [int] NOT NULL IDENTITY,
        [TenantId] [int] NOT NULL,
        [Nombre] [nvarchar](max),
        [Color] [nvarchar](max),
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.EstadoTurnoes] PRIMARY KEY ([Id])
    )
    CREATE TABLE [dbo].[Recursoes] (
        [Id] [int] NOT NULL IDENTITY,
        [TenantId] [int] NOT NULL,
        [Nombre] [nvarchar](100) NOT NULL,
        [Descripcion] [nvarchar](max),
        [Tipo] [int] NOT NULL,
        [Color] [nvarchar](7),
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.Recursoes] PRIMARY KEY ([Id])
    )
    CREATE TABLE [dbo].[RecursoServicios] (
        [Id] [int] NOT NULL IDENTITY,
        [TenantId] [int] NOT NULL,
        [RecursoId] [int] NOT NULL,
        [ServicioId] [int] NOT NULL,
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.RecursoServicios] PRIMARY KEY ([Id])
    )
    CREATE INDEX [IX_RecursoId] ON [dbo].[RecursoServicios]([RecursoId])
    CREATE INDEX [IX_ServicioId] ON [dbo].[RecursoServicios]([ServicioId])
    CREATE TABLE [dbo].[Servicios] (
        [Id] [int] NOT NULL IDENTITY,
        [TenantId] [int] NOT NULL,
        [Nombre] [nvarchar](max) NOT NULL,
        [Descripcion] [nvarchar](max),
        [Precio] [decimal](18, 2) NOT NULL,
        [DuracionMinutos] [int] NOT NULL,
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.Servicios] PRIMARY KEY ([Id])
    )
    CREATE TABLE [dbo].[Turnoes] (
        [Id] [int] NOT NULL IDENTITY,
        [TenantId] [int] NOT NULL,
        [ClienteId] [int] NOT NULL,
        [ServicioId] [int],
        [RecursoId] [int] NOT NULL,
        [EstadoTurnoId] [int] NOT NULL,
        [FechaHoraInicio] [datetime] NOT NULL,
        [FechaHoraFin] [datetime] NOT NULL,
        [Observaciones] [nvarchar](max),
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.Turnoes] PRIMARY KEY ([Id])
    )
    CREATE INDEX [IX_ClienteId] ON [dbo].[Turnoes]([ClienteId])
    CREATE INDEX [IX_ServicioId] ON [dbo].[Turnoes]([ServicioId])
    CREATE INDEX [IX_RecursoId] ON [dbo].[Turnoes]([RecursoId])
    CREATE INDEX [IX_EstadoTurnoId] ON [dbo].[Turnoes]([EstadoTurnoId])
    CREATE TABLE [dbo].[Users] (
        [Id] [int] NOT NULL IDENTITY,
        [Email] [nvarchar](max),
        [PasswordHash] [nvarchar](max),
        [Nombre] [nvarchar](max),
        [Role] [nvarchar](max),
        [TenantId] [int] NOT NULL,
        [CreatedAt] [datetime] NOT NULL,
        [UpdatedAt] [datetime],
        [IsActive] [bit] NOT NULL,
        CONSTRAINT [PK_dbo.Users] PRIMARY KEY ([Id])
    )
    ALTER TABLE [dbo].[ConfiguracionTenants] ADD CONSTRAINT [FK_dbo.ConfiguracionTenants_dbo.Tenants_TenantId] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants] ([Id]) ON DELETE CASCADE
    ALTER TABLE [dbo].[RecursoServicios] ADD CONSTRAINT [FK_dbo.RecursoServicios_dbo.Recursoes_RecursoId] FOREIGN KEY ([RecursoId]) REFERENCES [dbo].[Recursoes] ([Id]) ON DELETE CASCADE
    ALTER TABLE [dbo].[RecursoServicios] ADD CONSTRAINT [FK_dbo.RecursoServicios_dbo.Servicios_ServicioId] FOREIGN KEY ([ServicioId]) REFERENCES [dbo].[Servicios] ([Id]) ON DELETE CASCADE
    ALTER TABLE [dbo].[Turnoes] ADD CONSTRAINT [FK_dbo.Turnoes_dbo.Clientes_ClienteId] FOREIGN KEY ([ClienteId]) REFERENCES [dbo].[Clientes] ([Id]) ON DELETE CASCADE
    ALTER TABLE [dbo].[Turnoes] ADD CONSTRAINT [FK_dbo.Turnoes_dbo.EstadoTurnoes_EstadoTurnoId] FOREIGN KEY ([EstadoTurnoId]) REFERENCES [dbo].[EstadoTurnoes] ([Id]) ON DELETE CASCADE
    ALTER TABLE [dbo].[Turnoes] ADD CONSTRAINT [FK_dbo.Turnoes_dbo.Recursoes_RecursoId] FOREIGN KEY ([RecursoId]) REFERENCES [dbo].[Recursoes] ([Id])
    ALTER TABLE [dbo].[Turnoes] ADD CONSTRAINT [FK_dbo.Turnoes_dbo.Servicios_ServicioId] FOREIGN KEY ([ServicioId]) REFERENCES [dbo].[Servicios] ([Id])
    CREATE TABLE [dbo].[__MigrationHistory] (
        [MigrationId] [nvarchar](150) NOT NULL,
        [ContextKey] [nvarchar](300) NOT NULL,
        [Model] [varbinary](max) NOT NULL,
        [ProductVersion] [nvarchar](32) NOT NULL,
        CONSTRAINT [PK_dbo.__MigrationHistory] PRIMARY KEY ([MigrationId], [ContextKey])
    )
    INSERT [dbo].[__MigrationHistory]([MigrationId], [ContextKey], [Model], [ProductVersion])
    VALUES (N'202608182313336_Inicial', N'JKTurnos.Migrations.Configuration',   , N'6.4.4')
END


